  let currentLang = 'ar';

  // Toggle Language Handler
  const langToggleBtn = document.getElementById('lang-toggle-btn');
  const langFlag = document.getElementById('lang-flag');
  const langName = document.getElementById('lang-name');

  function setLanguage(lang) {
    currentLang = lang;
    const body = document.body;
    const html = document.documentElement;

    if (lang === 'ar') {
      body.classList.remove('lang-fr');
      body.classList.add('lang-ar');
      html.setAttribute('dir', 'rtl');
      html.setAttribute('lang', 'ar');
    } else {
      body.classList.remove('lang-ar');
      body.classList.add('lang-fr');
      html.setAttribute('dir', 'ltr');
      html.setAttribute('lang', 'fr');
    }

    // Update all elements with data-i18n
    const elements = document.querySelectorAll('[data-i18n]');
    elements.forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (translations[lang] && translations[lang][key]) {
        el.innerHTML = translations[lang][key];
      }
    });

    if (langName) langName.textContent = translations[lang].langBtn;
    if (langFlag) langFlag.textContent = translations[lang].langFlag;
  }

  if (langToggleBtn) {
    langToggleBtn.addEventListener('click', () => {
      setLanguage(currentLang === 'ar' ? 'fr' : 'ar');
    });
  }

  // ------------------------------------------------------------------------
  // 2. Real-Time Urgency Countdown Clock
  // ------------------------------------------------------------------------
  const cHours = document.getElementById('c-hours');
  const cMins = document.getElementById('c-mins');
  const cSecs = document.getElementById('c-secs');

  let remainingSeconds = 3 * 3600 + 48 * 60 + 21;

  setInterval(() => {
    if (remainingSeconds > 0) {
      remainingSeconds--;
    } else {
      remainingSeconds = 4 * 3600; // Reset urgency cycle
    }
    const h = Math.floor(remainingSeconds / 3600);
    const m = Math.floor((remainingSeconds % 3600) / 60);
    const s = remainingSeconds % 60;

    if (cHours) cHours.textContent = String(h).padStart(2, '0');
    if (cMins) cMins.textContent = String(m).padStart(2, '0');
    if (cSecs) cSecs.textContent = String(s).padStart(2, '0');
  }, 1000);

  // ------------------------------------------------------------------------
  // 3. Three.js 3D Interactive Blender Model
  // ------------------------------------------------------------------------
  const canvas = document.getElementById('blender-3d-canvas');
  let scene, camera, renderer, blenderGroup;
  let baseMesh, glassMesh, liquidMesh, bladeGroup;
  let isDragging = false;
  let previousMousePosition = { x: 0, y: 0 };

  const colorPalettes = {
    emerald: { base: 0x00A86B, accent: 0x00D084, name: 'أخضر زمردي فاخر (الأكثر طلباً)' },
    obsidian: { base: 0x1E293B, accent: 0x334155, name: 'أسود فحمي رياضي (Obsidian Black)' },
    pearl: { base: 0xE2E8F0, accent: 0xF8FAFC, name: 'أبيض لؤلؤي أنيق (Pure Pearl)' },
    coral: { base: 0xF87171, accent: 0xFB7185, name: 'وردي مرجاني مشرق (Coral Pink)' }
  };

  function init3D() {
    if (!canvas || typeof THREE === 'undefined') {
      console.warn('Three.js not loaded, canvas will render high-res fallback.');
      return;
    }

    const width = canvas.parentElement.clientWidth || 500;
    const height = canvas.parentElement.clientHeight || 440;

    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(40, width / height, 0.1, 1000);
    camera.position.set(0, 0, 7.5);

    renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    // Studio Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 1.4);
    scene.add(ambientLight);

    const dirLight1 = new THREE.DirectionalLight(0xffffff, 2.0);
    dirLight1.position.set(5, 8, 5);
    scene.add(dirLight1);

    const dirLight2 = new THREE.DirectionalLight(0x00D084, 1.2);
    dirLight2.position.set(-5, -2, -3);
    scene.add(dirLight2);

    blenderGroup = new THREE.Group();

    // 1. Motor Base Cylinder
    const baseGeo = new THREE.CylinderGeometry(1.15, 1.15, 1.6, 32);
    const baseMat = new THREE.MeshStandardMaterial({
      color: colorPalettes.emerald.base,
      roughness: 0.35,
      metalness: 0.2
    });
    baseMesh = new THREE.Mesh(baseGeo, baseMat);
    baseMesh.position.y = -1.1;
    blenderGroup.add(baseMesh);

    // Metallic ring at bottom
    const ringGeo = new THREE.CylinderGeometry(1.16, 1.16, 0.2, 32);
    const ringMat = new THREE.MeshStandardMaterial({ color: 0xCBD5E1, roughness: 0.15, metalness: 0.85 });
    const botRing = new THREE.Mesh(ringGeo, ringMat);
    botRing.position.y = -1.8;
    blenderGroup.add(botRing);

    // Power Button on Base
    const btnGeo = new THREE.CylinderGeometry(0.24, 0.24, 0.1, 24);
    btnGeo.rotateX(Math.PI / 2);
    const btnMat = new THREE.MeshStandardMaterial({ color: 0xFFFFFF, roughness: 0.2, metalness: 0.6 });
    const powerBtn = new THREE.Mesh(btnGeo, btnMat);
    powerBtn.position.set(0, -1.05, 1.12);
    blenderGroup.add(powerBtn);

    // Glowing Power Ring
    const glowRingGeo = new THREE.TorusGeometry(0.28, 0.04, 16, 32);
    const glowRingMat = new THREE.MeshBasicMaterial({ color: 0x00D084 });
    const glowRing = new THREE.Mesh(glowRingGeo, glowRingMat);
    glowRing.position.set(0, -1.05, 1.14);
    blenderGroup.add(glowRing);

    // 2. Glass Cylinder Body
    const glassGeo = new THREE.CylinderGeometry(1.1, 1.1, 2.2, 32);
    const glassMat = new THREE.MeshPhysicalMaterial({
      color: 0xFFFFFF,
      transmission: 0.92,
      opacity: 1,
      transparent: true,
      roughness: 0.08,
      ior: 1.5,
      thickness: 0.4
    });
    glassMesh = new THREE.Mesh(glassGeo, glassMat);
    glassMesh.position.y = 0.8;
    blenderGroup.add(glassMesh);

    // 3. Green Smoothie Liquid inside
    const liqGeo = new THREE.CylinderGeometry(1.02, 1.02, 1.8, 32);
    const liqMat = new THREE.MeshStandardMaterial({
      color: 0x34D399,
      roughness: 0.4,
      metalness: 0.1,
      transparent: true,
      opacity: 0.85
    });
    liquidMesh = new THREE.Mesh(liqGeo, liqMat);
    liquidMesh.position.y = 0.7;
    blenderGroup.add(liquidMesh);

    // 4. Stainless Steel 6-Blade Mechanism inside
    bladeGroup = new THREE.Group();
    for (let i = 0; i < 3; i++) {
      const bladeGeo = new THREE.BoxGeometry(1.2, 0.06, 0.18);
      const bladeMat = new THREE.MeshStandardMaterial({ color: 0xE2E8F0, metalness: 0.95, roughness: 0.15 });
      const blade = new THREE.Mesh(bladeGeo, bladeMat);
      blade.rotation.y = (i * Math.PI) / 3;
      bladeGroup.add(blade);
    }
    bladeGroup.position.y = -0.2;
    blenderGroup.add(bladeGroup);

    // 5. Top Lid Cylinder
    const lidGeo = new THREE.CylinderGeometry(1.12, 1.12, 0.7, 32);
    const lidMat = new THREE.MeshStandardMaterial({
      color: colorPalettes.emerald.base,
      roughness: 0.35,
      metalness: 0.2
    });
    const topLid = new THREE.Mesh(lidGeo, lidMat);
    topLid.position.y = 2.25;
    blenderGroup.add(topLid);

    // Lid Metal Band
    const lidBandGeo = new THREE.CylinderGeometry(1.13, 1.13, 0.15, 32);
    const lidBand = new THREE.Mesh(lidBandGeo, ringMat);
    lidBand.position.y = 1.95;
    blenderGroup.add(lidBand);

    // Strap loop on top
    const strapGeo = new THREE.TorusGeometry(0.35, 0.08, 16, 24);
    strapGeo.rotateY(Math.PI / 2);
    const strapMat = new THREE.MeshStandardMaterial({ color: colorPalettes.emerald.accent, roughness: 0.8 });
    const strap = new THREE.Mesh(strapGeo, strapMat);
    strap.position.set(0.85, 2.35, 0);
    blenderGroup.add(strap);

    scene.add(blenderGroup);

    // Drag to rotate controls
    const wrapper = canvas.parentElement;

    wrapper.addEventListener('mousedown', (e) => {
      isDragging = true;
      previousMousePosition = { x: e.clientX, y: e.clientY };
    });

    window.addEventListener('mouseup', () => { isDragging = false; });

    wrapper.addEventListener('mousemove', (e) => {
      if (!isDragging || !blenderGroup) return;
      const deltaX = e.clientX - previousMousePosition.x;
      const deltaY = e.clientY - previousMousePosition.y;

      blenderGroup.rotation.y += deltaX * 0.012;
      blenderGroup.rotation.x += deltaY * 0.012;
      // Clamp x
      blenderGroup.rotation.x = Math.max(-0.6, Math.min(0.6, blenderGroup.rotation.x));

      previousMousePosition = { x: e.clientX, y: e.clientY };
    });

    // Touch support for mobile devices
    wrapper.addEventListener('touchstart', (e) => {
      if (e.touches.length === 1) {
        isDragging = true;
        previousMousePosition = { x: e.touches[0].clientX, y: e.touches[0].clientY };
      }
    }, { passive: true });

    window.addEventListener('touchend', () => { isDragging = false; });

    wrapper.addEventListener('touchmove', (e) => {
      if (!isDragging || !blenderGroup || e.touches.length !== 1) return;
      const deltaX = e.touches[0].clientX - previousMousePosition.x;
      const deltaY = e.touches[0].clientY - previousMousePosition.y;

      blenderGroup.rotation.y += deltaX * 0.012;
      blenderGroup.rotation.x += deltaY * 0.012;
      blenderGroup.rotation.x = Math.max(-0.6, Math.min(0.6, blenderGroup.rotation.x));

      previousMousePosition = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    }, { passive: true });

    // Animation Loop
    function animate() {
      requestAnimationFrame(animate);

      if (!isDragging && blenderGroup) {
        blenderGroup.rotation.y += 0.005; // Gentle continuous auto-spin
      }

      if (bladeGroup) {
        bladeGroup.rotation.y += 0.05; // Spin blades gently
      }

      renderer.render(scene, camera);
    }
    animate();

    // Responsive Canvas Resize
    window.addEventListener('resize', () => {
      if (!canvas || !renderer || !camera) return;
      const newW = canvas.parentElement.clientWidth;
      const newH = canvas.parentElement.clientHeight;
      camera.aspect = newW / newH;
      camera.updateProjectionMatrix();
      renderer.setSize(newW, newH);
    });
  }

  init3D();

  // Color Variant Buttons
  const colorDots = document.querySelectorAll('.c-dot');
  const colorTitle = document.getElementById('selected-color-title');

  colorDots.forEach(btn => {
    btn.addEventListener('click', () => {
      colorDots.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const colorKey = btn.getAttribute('data-color');
      const palette = colorPalettes[colorKey];

      if (palette && baseMesh) {
        baseMesh.material.color.setHex(palette.base);
        if (colorTitle) colorTitle.textContent = palette.name;
      }
    });
  });

  // ------------------------------------------------------------------------
  // 4. Offer Bundles (Pack Selection Logic)
  // ------------------------------------------------------------------------
  const packCards = document.querySelectorAll('.offer-pack-card');
  const sumPackName = document.getElementById('sum-pack-name');
  const sumTotalPrice = document.getElementById('sum-total-price');
  const heroDisplayPrice = document.getElementById('hero-display-price');
  const stickyPriceVal = document.getElementById('sticky-price-val');
  let selectedPackNumber = '2';
  let selectedPackPrice = '399';

  const packNames = {
    '1': { ar: 'قطعة واحدة (1 خلاط ذكي)', fr: '1 Pièce (1 Mixeur Smart)' },
    '2': { ar: 'قطعتين (2 خلاطات ذكية) — الأكثر طلباً 🔥', fr: '2 Pièces (Pack Duo) — Plus Populaire 🔥' },
    '3': { ar: '3 قطع (عرض العائلة) + هدية قيمة 🎁', fr: '3 Pièces (Pack Famille) + Cadeau 🎁' }
  };

  packCards.forEach(card => {
    card.addEventListener('click', () => {
      packCards.forEach(c => {
        c.classList.remove('active');
        const circle = c.querySelector('.pack-radio-circle');
        if (circle) circle.classList.remove('checked');
      });

      card.classList.add('active');
      const circle = card.querySelector('.pack-radio-circle');
      if (circle) circle.classList.add('checked');

      selectedPackNumber = card.getAttribute('data-pack');
      selectedPackPrice = card.getAttribute('data-price');

      if (sumPackName) {
        sumPackName.textContent = packNames[selectedPackNumber][currentLang];
      }
      if (sumTotalPrice) {
        sumTotalPrice.textContent = `${selectedPackPrice} درهم`;
      }
      if (heroDisplayPrice) {
        heroDisplayPrice.textContent = selectedPackPrice;
      }
      if (stickyPriceVal) {
        stickyPriceVal.textContent = `${selectedPackPrice} درهم`;
      }
    });
  });

  // ------------------------------------------------------------------------
  // 5. Moroccan COD Form Submission & Validation
  // ------------------------------------------------------------------------
  const codForm = document.getElementById('moroccan-cod-form');
  const successModal = document.getElementById('success-modal');
  const btnCloseModal = document.getElementById('btn-close-modal');
  const confirmName = document.getElementById('confirm-name');
  const confirmCity = document.getElementById('confirm-city');
  const confirmPack = document.getElementById('confirm-pack');
  const orderRefNum = document.getElementById('order-ref-num');

  if (codForm) {
    codForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const nameInput = document.getElementById('client-name');
      const phoneInput = document.getElementById('client-phone');
      const citySelect = document.getElementById('client-city');
      const addressInput = document.getElementById('client-address');

      const nameVal = nameInput ? nameInput.value.trim() : '';
      const phoneVal = phoneInput ? phoneInput.value.trim() : '';
      const cityVal = citySelect ? citySelect.value : '';
      const addressVal = addressInput ? addressInput.value.trim() : '';

      // Validation
      if (!nameVal) {
        alert(currentLang === 'ar' ? 'يرجى إدخال اسمكم الكامل' : 'Veuillez saisir votre nom complet');
        nameInput.focus();
        return;
      }

      if (!phoneVal || phoneVal.length < 9) {
        alert(currentLang === 'ar' ? 'يرجى إدخال رقم هاتف صحيح للتواصل معك' : 'Veuillez saisir un numéro de téléphone valide');
        phoneInput.focus();
        return;
      }

      if (!cityVal) {
        alert(currentLang === 'ar' ? 'يرجى اختيار مدينتك بالمغرب' : 'Veuillez sélectionner votre ville');
        citySelect.focus();
        return;
      }

      if (!addressVal) {
        alert(currentLang === 'ar' ? 'يرجى إدخال عنوان التسليم أو الحي' : 'Veuillez saisir votre adresse ou quartier');
        addressInput.focus();
        return;
      }

      // Generate random order reference (e.g., #YC-4892)
      const randomRef = '#YC-' + Math.floor(1000 + Math.random() * 9000);
      if (orderRefNum) orderRefNum.textContent = randomRef;
      if (confirmName) confirmName.textContent = nameVal;
      if (confirmCity) confirmCity.textContent = cityVal;
      if (confirmPack) confirmPack.textContent = `${packNames[selectedPackNumber][currentLang]} (${selectedPackPrice} MAD)`;

      // Open celebration modal
      if (successModal) {
        successModal.classList.add('open');
        successModal.setAttribute('aria-hidden', 'false');
      }

      // Reset form
      codForm.reset();
    });
  }

  if (btnCloseModal && successModal) {
    btnCloseModal.addEventListener('click', () => {
      successModal.classList.remove('open');
      successModal.setAttribute('aria-hidden', 'true');
    });
  }

  // ------------------------------------------------------------------------
  // 6. Recent Live Purchase Toast (Abdou Ecom Scarcity Trigger)
  // ------------------------------------------------------------------------
  const purchaseToast = document.getElementById('purchase-toast');
  const toastBuyer = document.getElementById('toast-buyer');
  const toastOffer = document.getElementById('toast-offer');
  const toastAgo = document.getElementById('toast-ago');

  const livePurchases = [
    { name: 'كمال من الدار البيضاء', offer: 'خلاط YouCan الذكي (عرض قطعتين 🔥)', time: 'قبل دقيقة واحدة' },
    { name: 'ياسين من مراكش', offer: 'خلاط YouCan الذكي (عرض قطعتين 🔥)', time: 'قبل 3 دقائق' },
    { name: 'مريم من الرباط', offer: 'خلاط YouCan الذكي (عرض فردي 1 قطعة)', time: 'قبل 5 دقائق' },
    { name: 'أمين من طنجة', offer: 'خلاط YouCan الذكي (عرض العائلة 3 قطع 🎁)', time: 'قبل 8 دقائق' },
    { name: 'سناء من أكادير', offer: 'خلاط YouCan الذكي (عرض قطعتين 🔥)', time: 'قبل 12 دقيقة' }
  ];

  let purchaseIndex = 0;

  function showRecentPurchase() {
    if (!purchaseToast) return;
    const item = livePurchases[purchaseIndex % livePurchases.length];
    purchaseIndex++;

    if (toastBuyer) toastBuyer.textContent = `اشترى ${item.name}`;
    if (toastOffer) toastOffer.textContent = item.offer;
    if (toastAgo) toastAgo.textContent = `${item.time} · تم الشحن 🚚`;

    purchaseToast.classList.add('show');

    setTimeout(() => {
      purchaseToast.classList.remove('show');
    }, 4500);
  }

  // First popup after 4 seconds, then every 16 seconds
  setTimeout(showRecentPurchase, 4000);
  setInterval(showRecentPurchase, 16000);

  // ------------------------------------------------------------------------
  // 7. Gallery Thumbnail Switcher
  // ------------------------------------------------------------------------
  const thumbBtns = document.querySelectorAll('.thumb-btn');
  const canvas3DWrapper = document.getElementById('canvas-3d-wrapper');

  thumbBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      thumbBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      const imgVal = btn.getAttribute('data-img');
      if (imgVal === '3d') {
        // Show 3D Canvas
        if (canvas) canvas.style.display = 'block';
        const existingImg = canvas3DWrapper.querySelector('.preview-static-img');
        if (existingImg) existingImg.remove();
      } else {
        // Show photo preview inside box
        if (canvas) canvas.style.display = 'none';
        let staticImg = canvas3DWrapper.querySelector('.preview-static-img');
        if (!staticImg) {
          staticImg = document.createElement('img');
          staticImg.className = 'preview-static-img';
          staticImg.style.width = '100%';
          staticImg.style.height = '100%';
          staticImg.style.objectFit = 'cover';
          canvas3DWrapper.appendChild(staticImg);
        }
        staticImg.src = imgVal;
      }
    });
  });

});
